import java.util.*;

class FileSharing {
  private final Map<Integer, TreeSet<Integer>> owners = new HashMap<>(); // chunk -> users holding it
  private final Map<Integer, Set<Integer>> chunks = new HashMap<>(); // user -> chunks held
  private final PriorityQueue<Integer> freeIds = new PriorityQueue<>();
  private int nextId = 1;

  public FileSharing(int m) {}

  public int join(List<Integer> ownedChunks) {
    int id = freeIds.isEmpty() ? nextId++ : freeIds.poll();
    chunks.put(id, new HashSet<>(ownedChunks));
    for (int c : ownedChunks) owners.computeIfAbsent(c, k -> new TreeSet<>()).add(id);
    return id;
  }

  public void leave(int userID) {
    for (int c : chunks.remove(userID)) owners.get(c).remove(userID);
    freeIds.add(userID);
  }

  public List<Integer> request(int userID, int chunkID) {
    TreeSet<Integer> who = owners.getOrDefault(chunkID, new TreeSet<>());
    List<Integer> res = new ArrayList<>(who);
    if (!res.isEmpty() && chunks.get(userID).add(chunkID)) owners.computeIfAbsent(chunkID, k -> new TreeSet<>()).add(userID);
    return res;
  }
}
